//! 🏗️ Actual System receipts, original caller custody and every partial native Session birth.
use semio_s_spatial_kernel_semio_session::{SessionConstructionCursor,SessionCapture};
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation,OriginalTurnFailure};
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress};
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn clock()->Option<u64>{Some(1000)}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn stock(law:&serde_json::Value)->Grant{let row=&law["stock"];Grant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_copy_bytes:row["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:row["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:row["release"].as_u64().unwrap()as usize,maximum_depth:row["depth"].as_u64().unwrap()as usize}}
fn original_caller(law:&serde_json::Value)->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(944),Generation(31),stock(law),clock,law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap())}
fn capture_close(capture:&mut SessionCapture,caller:&mut OriginalJobFixtureCaller,policy:Grant){
 for _ in 0..100_000{if capture.terminal_is_empty(){return}let before=caller.cumulative_receipt();let(step,heap)=observe(||caller.turn(policy,|cx|{let grant=cx.retained_grant();let copy=capture.next_close_copy_byte_demand()?;if cx.should_yield()||grant.maximum_items==0||grant.maximum_depth<capture.next_close_depth_demand()?.max(1)||grant.maximum_copy_bytes<copy||grant.maximum_capacity_bytes<capture.next_close_capacity_byte_demand(grant.maximum_copy_bytes)?||grant.maximum_release_bytes<capture.next_close_release_byte_demand()?{return Ok(Progress::default())}cx.consume_fuel(1);let progress=capture.close_step(grant).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?.progress();cx.consume_retained(progress)?;Ok(progress)}));let progress=step.unwrap();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(caller.cumulative_receipt(),before.checked_add(progress).unwrap());assert!(progress!=Progress::default(),"funded capture close must advance")}
 panic!("actual original capture did not close")
}
fn constructor_close(cursor:&mut SessionConstructionCursor,caller:&mut OriginalJobFixtureCaller,policy:Grant){
 for _ in 0..100_000{if cursor.terminal_is_empty(){return}let(step,heap)=observe(||caller.turn(policy,|cx|cursor.close_step(cx)));let progress=step.unwrap().progress();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress!=Progress::default(),"funded partial constructor close must advance")}
 panic!("partial original constructor did not close")
}

#[test]
fn original_session_constructor_pays_each_exact_birth_and_preserves_original_caller(){
 let law=fixture();for body in law["copyGrants"].as_array().unwrap(){let stock=stock(&law);let policy=Grant{maximum_copy_bytes:body.as_u64().unwrap()as usize,..stock};let mut caller=original_caller(&law);let mut cursor=SessionConstructionCursor::new(&());let mut recipient=0;let mut source=0;let mut capture=None;let mut born=0;let root_born=caller.born_bytes();let original_cancel=caller.cancel()as*const _;
  for expected in 0..law["phases"].as_array().unwrap().len(){assert_eq!(cursor.phase(),expected as u8);let demand=cursor.next_demand(policy.maximum_copy_bytes).unwrap();let mut denied=vec![Grant{maximum_items:0,..policy},Grant{maximum_depth:0,..policy}];if demand.capacity_bytes!=0{denied.push(Grant{maximum_capacity_bytes:demand.capacity_bytes-1,..policy})}
   for loan in denied{let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(step,heap)=observe(||caller.turn(loan,|cx|cursor.step(cx)));assert!(step.unwrap().ready.is_none());assert_eq!(heap,(0,0));assert_eq!(cursor.phase(),expected as u8);assert_eq!(caller.receipt(),Progress::default());assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel)}
   for (fuel,deadline) in [(0,1_000_000),(1,1000)]{let before=caller.cumulative_receipt();let issued=caller.fuel_remaining();let(step,heap)=observe(||caller.turn(policy,|cx|{let mut ready=None;cx.with_original_work_loan(fuel,deadline,|same|{ready=cursor.step(same)?.ready;Ok(())})?;Ok(ready)}));assert!(step.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(cursor.phase(),expected as u8);assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),issued)}
   let fuel=caller.fuel_remaining();let(step,heap)=observe(||caller.turn(policy,|cx|{let actual_recipient=cx.original_recipient_identity();let actual_source=cx.original_source_parent()?.source_identity()?;if recipient==0{recipient=actual_recipient;source=actual_source}assert_eq!(actual_recipient,recipient);assert_eq!(actual_source,source);assert_eq!(cx.operation(),OperationId(944));assert_eq!(cx.generation(),Generation(31));assert_eq!(cx.original_cancel_token()as*const _,original_cancel);assert_eq!(cx.deadline_us(),law["deadline"].as_u64().unwrap());cursor.step(cx)}));let step=step.unwrap();assert_eq!(step.progress,caller.receipt());assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));assert_eq!(heap.0,demand.capacity_bytes);assert_eq!(caller.fuel_remaining(),fuel-1);assert_eq!(cursor.phase(),expected as u8+1);born+=heap.0;if expected==0{let mut foreign=original_caller(&law);let before=foreign.cumulative_receipt();let fuel=foreign.fuel_remaining();let phase=cursor.phase();let(result,heap)=observe(||foreign.turn(policy,|cx|cursor.step(cx)));assert!(result.is_err());assert_eq!(heap,(law["foreignSourceEffects"].as_u64().unwrap()as usize,0));assert_eq!(cursor.phase(),phase);assert_eq!(foreign.cumulative_receipt(),before);assert_eq!(foreign.fuel_remaining(),fuel);let born=foreign.born_bytes();let(released,heap)=observe(||foreign.retire(policy));assert_eq!(released,born);assert_eq!(heap,(0,born));}if step.ready.is_some(){capture=step.ready;}
  }
  assert!(cursor.terminal_is_empty());let mut capture=capture.unwrap();assert!(!capture.is_closed());capture_close(&mut capture,&mut caller,policy);let before=caller.cumulative_receipt();let(_,heap)=observe(||{drop(capture);drop(cursor)});assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);let(receipt,heap)=observe(||caller.retire(policy));assert_eq!(heap,(0,receipt));assert_eq!(receipt,root_born);assert_eq!(before.retained_capacity_bytes,born+root_born);assert_eq!(before.released_bytes,before.retained_capacity_bytes-root_born);
 }
}

#[test]
fn original_session_constructor_cancellation_closes_only_born_originals(){
 let law=fixture();for body in law["copyGrants"].as_array().unwrap(){for stop in law["cancelStops"].as_array().unwrap(){let policy=Grant{maximum_copy_bytes:body.as_u64().unwrap()as usize,..stock(&law)};let mut caller=original_caller(&law);let mut cursor=SessionConstructionCursor::new(&());let root_born=caller.born_bytes();
   for _ in 0..stop.as_u64().unwrap(){let(step,heap)=observe(||caller.turn(policy,|cx|cursor.step(cx)));let step=step.unwrap();assert!(step.ready.is_none());assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));assert_eq!(step.progress,caller.receipt())}
   semio_framework_async::poll::resolve_ready(caller.cancel().cancel());cursor.begin_close();let phase=cursor.phase();let demand=cursor.next_demand(policy.maximum_copy_bytes).unwrap();let mut denied=vec![Grant{maximum_items:0,..policy},Grant{maximum_depth:0,..policy}];if demand.release_bytes!=0{denied.push(Grant{maximum_release_bytes:demand.release_bytes-1,..policy})}
   for loan in denied{let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(step,heap)=observe(||caller.turn(loan,|cx|cursor.close_step(cx)));assert_eq!(step.unwrap().progress(),Progress::default());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel);assert_eq!(cursor.phase(),phase)}
   constructor_close(&mut cursor,&mut caller,policy);assert_eq!(cursor.phase(),phase);let before=caller.cumulative_receipt();let(_,heap)=observe(||drop(cursor));assert_eq!(heap,(0,0));let(receipt,heap)=observe(||caller.retire(policy));assert_eq!(heap,(0,receipt));assert_eq!(receipt,root_born);assert_eq!(before.released_bytes,before.retained_capacity_bytes-root_born);
  }}
}
